import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'ok' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Marketing Site', quotaPercent: 42, status: 'ok' },
  { id: 'p2', name: 'Analytics Pipeline', quotaPercent: 88, status: 'warning' },
  { id: 'p3', name: 'Payments Gateway', quotaPercent: 112, status: 'over' },
  { id: 'p4', name: 'Support Portal', quotaPercent: 15, status: 'ok' },
  { id: 'p5', name: 'Mobile Backend', quotaPercent: 76, status: 'warning' },
  { id: 'p6', name: 'Search Service', quotaPercent: 130, status: 'over' },
  { id: 'p7', name: 'Docs Site', quotaPercent: 5, status: 'ok' },
  { id: 'p8', name: 'Notification Hub', quotaPercent: 95, status: 'warning' },
  { id: 'p9', name: 'Data Warehouse', quotaPercent: 60, status: 'ok' },
  { id: 'p10', name: 'CDN Origin', quotaPercent: 104, status: 'over' },
  { id: 'p11', name: 'Internal Tools', quotaPercent: 33, status: 'ok' },
  { id: 'p12', name: 'Fraud Detection', quotaPercent: 81, status: 'warning' },
];

const ALL_STATUSES: ProjectStatus[] = ['ok', 'warning', 'over'];

const STATUS_LABEL: Record<ProjectStatus, string> = {
  ok: 'В рамках квоты',
  warning: 'Приближается к лимиту',
  over: 'Квота превышена',
};

const STATUS_BADGE_VARIANT: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  ok: 'success',
  warning: 'warning',
  over: 'danger',
};

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const totalPages = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);

  const pageProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE
  );

  const handleRemoveStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => prev.filter((item) => item !== status));
    setPage(1);
  };

  const handleResetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(1);
  };

  const handlePageChange = (nextPage: number) => {
    setPage(nextPage);
  };

  return (
    <div className="jx-stack jx-stack-lg">
      <div className="jx-cluster jx-cluster-sm" role="group" aria-label="Фильтры по статусу">
        {activeStatuses.length === 0 ? (
          <span className="jx-text jx-text-muted">Фильтры не выбраны</span>
        ) : (
          activeStatuses.map((status) => (
            <JxChip
              key={status}
              variant={STATUS_BADGE_VARIANT[status]}
              onRemove={() => handleRemoveStatus(status)}
            >
              {STATUS_LABEL[status]}
            </JxChip>
          ))
        )}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          description="Под текущие фильтры не попадает ни один проект."
        >
          <JxButton variant="primary" onClick={handleResetFilters}>
            Сбросить фильтры
          </JxButton>
        </JxEmptyState>
      ) : (
        <>
          <ul className="jx-list jx-stack jx-stack-sm" style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {pageProjects.map((project) => (
              <li
                key={project.id}
                className="jx-cluster jx-cluster-md jx-panel"
                style={{
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: 'var(--jx-space-md)',
                  borderRadius: 'var(--jx-radius-md)',
                  border: '1px solid var(--jx-color-border)',
                }}
              >
                <span className="jx-text jx-text-strong">{project.name}</span>

                <div className="jx-cluster jx-cluster-sm" style={{ alignItems: 'center' }}>
                  <JxProgressCircle
                    value={Math.min(project.quotaPercent, 100)}
                    max={100}
                    size="sm"
                    variant={STATUS_BADGE_VARIANT[project.status]}
                    label={`${project.quotaPercent}%`}
                  />
                  <JxBadge variant={STATUS_BADGE_VARIANT[project.status]}>
                    {STATUS_LABEL[project.status]}
                  </JxBadge>
                </div>
              </li>
            ))}
          </ul>

          <JxPagination
            page={currentPage}
            pageSize={PAGE_SIZE}
            totalItems={filteredProjects.length}
            onPageChange={handlePageChange}
          />
        </>
      )}
    </div>
  );
}

